use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's `HTTPClient<[...]>` grant covers.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host from an http(s) URL. Returns `None` for anything whose
/// authority carries userinfo (`user@host`) or has no host, so that such URLs
/// are never matched against the allowlist by accident.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    if authority.contains('@') {
        return None;
    }
    let host = authority.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(host: &str) -> bool {
    ALLOWED_HOSTS.iter().any(|h| h.eq_ignore_ascii_case(host))
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            // Pre-check against the allowlist so an out-of-scope URL is recorded
            // as a failure for this feed rather than trapping the whole run.
            // The host still enforces the allowlist at the crossing.
            let permitted = host_of(&url).is_some_and(is_allowed);
            if !permitted {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            // Transport failures (timeout, error status, oversize) come back as
            // values, so one dead feed does not fail the tick.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

I did not add the `last-input` write to the shared store. The node's `with` clause grants only `aap:caps/http-client@0.1.0`. Writing that key requires importing `aap:caps/state-rw`, which is outside the grant. A prose approval doesn't change the grant the host enforces, and storing untrusted feed input in shared state needs its own review. If the platform team wants this, the grant itself needs to be extended. The output above is unaffected by this omission.

